using System.IO;
using System.Windows.Media;
using System.Windows.Media.Imaging;

namespace PicotooPet.Desktop.Views.Controls;

/// <summary>把已确认参考图中的阿拉斯加视觉随程序集一起封装，避免运行时依赖外部路径或网络。</summary>
public static class AssistantArtworkData
{
    // 资源逻辑名保持稳定，便于视觉合同和后续正式美术文件替换。
    public const string HeroAssetName     = "alaskan-hero.png";
    public const string WorkingAssetName  = "alaskan-working.png";
    public const string RestingAssetName  = "alaskan-resting.png";
    public const string SleepingAssetName = "alaskan-sleeping.png";

    private static readonly Lazy<ImageSource> HeroSource     = new(() => Decode(HeroBase64));
    private static readonly Lazy<ImageSource> WorkingSource  = new(() => Decode(WorkingBase64));
    private static readonly Lazy<ImageSource> RestingSource  = new(() => Decode(RestingBase64));
    private static readonly Lazy<ImageSource> SleepingSource = new(() => Decode(SleepingBase64));

    /// <summary>Hero 使用确认稿中的真实感阿拉斯加视觉。</summary>
    public static ImageSource Hero => HeroSource.Value;

    /// <summary>真实执行时使用耳机/电脑工作视觉。</summary>
    public static ImageSource Working => WorkingSource.Value;

    /// <summary>在线但没有真实执行时使用休息/泡澡视觉。</summary>
    public static ImageSource Resting => RestingSource.Value;

    /// <summary>控制链不可用时使用睡眠视觉。</summary>
    public static ImageSource Sleeping => SleepingSource.Value;

    private static ImageSource Decode(string encoded)
    {
        var bytes = Convert.FromBase64String(encoded);
        using var stream = new MemoryStream(bytes, writable: false);
        var bitmap = new BitmapImage();
        bitmap.BeginInit();
        bitmap.CacheOption  = BitmapCacheOption.OnLoad;
        bitmap.StreamSource = stream;
        bitmap.EndInit();
        bitmap.Freeze();
        return bitmap;
    }

    private const string HeroBase64 = "";
    private const string WorkingBase64 = "";
    private const string RestingBase64 = "";
    private const string RestingBase64 = "";
    private const string SleepingBase64 = "";
}
